using System.Security.Claims;
using Microsoft.EntityFrameworkCore;
namespace TheBarcode.Api;

public static class ApiEndpoints
{
    public static void MapBarcodeApi(this WebApplication app, string jwt)
    {
        var api = app.MapGroup("/api"); api.MapGet("/health", () => Results.Ok(new { status = "healthy", time = DateTimeOffset.UtcNow })); api.MapPost("/auth/login", async (LoginRequest req, AppDbContext db) => { var u = await db.Staff.FindAsync(req.StaffId); return u is null || !u.Active || !Security.VerifyPin(req.Pin, u.PinHash) ? Results.Unauthorized() : Results.Ok(new { token = Security.Token(u, jwt), user = new { u.Id, u.Name, u.Role } }); }); api.MapGet("/bootstrap", async (AppDbContext db) => Results.Ok(new { products = await db.Products.OrderBy(x => x.Category).ThenBy(x => x.Name).ToListAsync(), customers = await db.Customers.Where(x => x.Active).OrderBy(x => x.Name).ToListAsync(), staff = await db.Staff.Where(x => x.Active).Select(x => new { x.Id, x.Name, x.Role, x.IsDemo }).ToListAsync() }));
        var secured = api.MapGroup("").RequireAuthorization(); secured.MapGet("/settings", async (AppDbContext db) => Results.Ok(new { organization = await db.Organizations.FirstAsync(), receipt = await db.ReceiptConfigurations.FirstAsync(), branches = await db.Branches.OrderBy(x => x.Name).ToListAsync(), terminals = await db.Terminals.OrderBy(x => x.Name).ToListAsync() })); secured.MapPut("/settings/organization", async (OrganizationRequest r, AppDbContext db, ClaimsPrincipal principal) => { if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.IndustryProfile) || string.IsNullOrWhiteSpace(r.Currency)) return Results.BadRequest(new { error = "Business name, industry profile and currency are required" }); var x = await db.Organizations.FirstAsync(); x.Name = r.Name.Trim(); x.LegalName = r.LegalName?.Trim(); x.IndustryProfile = r.IndustryProfile; x.Currency = r.Currency; x.Phone = r.Phone?.Trim(); x.Email = r.Email?.Trim(); x.Address = r.Address?.Trim(); x.TaxPin = r.TaxPin?.Trim(); x.VatNumber = r.VatNumber?.Trim(); x.Tagline = r.Tagline?.Trim(); x.UpdatedAt = DateTimeOffset.UtcNow; db.AuditEvents.Add(Audit(principal, "Updated", "Organization", x.Id.ToString(), $"Business profile: {x.Name}")); await db.SaveChangesAsync(); return Results.Ok(x); }).RequireAuthorization(p => p.RequireRole("Owner", "Manager")); secured.MapPut("/settings/receipt", async (ReceiptConfigurationRequest r, AppDbContext db, ClaimsPrincipal principal) => { if (r.PaperWidthMm is not (58 or 80) || r.Copies is < 1 or > 3 || !new[] { "Never", "Optional", "Automatic" }.Contains(r.CreditSalePrintMode) || !new[] { "Never", "Optional", "Automatic" }.Contains(r.PaymentReceiptPrintMode)) return Results.BadRequest(new { error = "Invalid receipt configuration" }); var x = await db.ReceiptConfigurations.FirstAsync(); x.PaperWidthMm = r.PaperWidthMm; x.ShowBusinessDetails = r.ShowBusinessDetails; x.ShowCustomer = r.ShowCustomer; x.ShowCashier = r.ShowCashier; x.ShowTax = r.ShowTax; x.ShowCustomerBalance = r.ShowCustomerBalance; x.ShowPoweredBy = r.ShowPoweredBy; x.AutoPrintPaidSale = r.AutoPrintPaidSale; x.CreditSalePrintMode = r.CreditSalePrintMode; x.PaymentReceiptPrintMode = r.PaymentReceiptPrintMode; x.Copies = r.Copies; x.Footer = r.Footer.Trim(); x.ReceiptPrefix = r.ReceiptPrefix.Trim(); x.InvoicePrefix = r.InvoicePrefix.Trim(); x.PaymentPrefix = r.PaymentPrefix.Trim(); x.UpdatedAt = DateTimeOffset.UtcNow; db.AuditEvents.Add(Audit(principal, "Updated", "ReceiptConfiguration", x.Id.ToString(), $"{x.PaperWidthMm}mm, {x.Copies} copy/copies")); await db.SaveChangesAsync(); return Results.Ok(x); }).RequireAuthorization(p => p.RequireRole("Owner", "Manager")); secured.MapPut("/settings/branches", async (BranchRequest r, AppDbContext db, ClaimsPrincipal principal) => { if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Code)) return Results.BadRequest(new { error = "Branch name and code are required" }); var x = r.Id is Guid id ? await db.Branches.FindAsync(id) : null; if (x is null) { x = new Branch(); db.Branches.Add(x); } x.Name = r.Name.Trim(); x.Code = r.Code.Trim().ToUpperInvariant(); x.Address = r.Address?.Trim(); x.Phone = r.Phone?.Trim(); x.Active = r.Active; x.UpdatedAt = DateTimeOffset.UtcNow; db.AuditEvents.Add(Audit(principal, r.Id is null ? "Created" : "Updated", "Branch", x.Id.ToString(), x.Name)); await db.SaveChangesAsync(); return Results.Ok(x); }).RequireAuthorization(p => p.RequireRole("Owner", "Manager")); secured.MapPut("/settings/terminals", async (TerminalRequest r, AppDbContext db, ClaimsPrincipal principal) => { if (!await db.Branches.AnyAsync(x => x.Id == r.BranchId) || string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.DeviceKey)) return Results.BadRequest(new { error = "Valid branch, terminal name and device key are required" }); var x = r.Id is Guid id ? await db.Terminals.FindAsync(id) : null; if (x is null) { x = new Terminal(); db.Terminals.Add(x); } x.BranchId = r.BranchId; x.Name = r.Name.Trim(); x.DeviceKey = r.DeviceKey.Trim(); x.Active = r.Active; x.UpdatedAt = DateTimeOffset.UtcNow; db.AuditEvents.Add(Audit(principal, r.Id is null ? "Created" : "Updated", "Terminal", x.Id.ToString(), x.Name)); await db.SaveChangesAsync(); return Results.Ok(x); }).RequireAuthorization(p => p.RequireRole("Owner", "Manager")); secured.MapGet("/products", async (AppDbContext db) => await db.Products.OrderBy(x => x.Category).ThenBy(x => x.Name).ToListAsync()); secured.MapPost("/products", async (ProductRequest r, AppDbContext db, ClaimsPrincipal principal) => { var p = new Product { Name = r.Name, Category = r.Category, Barcode = r.Barcode, Unit = r.Unit, CostPrice = r.CostPrice, SellingPrice = r.SellingPrice, Stock = r.Stock, MinStock = r.MinStock, Sellable = r.Sellable }; db.Products.Add(p); db.AuditEvents.Add(Audit(principal, "Created", "Product", p.Id.ToString(), p.Name)); await db.SaveChangesAsync(); return Results.Created($"/api/products/{p.Id}", p); }).RequireAuthorization(p => p.RequireRole("Owner", "Manager", "Storekeeper"));
        secured.MapGet("/staff", async (AppDbContext db) => await db.Staff.OrderBy(x => x.Name).Select(x => new { x.Id, x.Name, x.Role, x.Active, x.CreatedAt }).ToListAsync()).RequireAuthorization(p => p.RequireRole("Owner")); secured.MapPost("/staff", async (StaffRequest r, AppDbContext db, ClaimsPrincipal principal) => { var roles = new[] { "Owner", "Manager", "Cashier", "Storekeeper", "Auditor" }; if (string.IsNullOrWhiteSpace(r.Name) || r.Pin.Length < 6 || !roles.Contains(r.Role)) return Results.BadRequest(new { error = "Name, a 6-character PIN and a valid role are required" }); var user = new StaffUser { Name = r.Name.Trim(), PinHash = Security.HashPin(r.Pin), Role = r.Role }; db.Staff.Add(user); db.AuditEvents.Add(Audit(principal, "Created", "Staff", user.Id.ToString(), $"{user.Name} · {user.Role}")); await db.SaveChangesAsync(); return Results.Created($"/api/staff/{user.Id}", new { user.Id, user.Name, user.Role, user.Active, user.CreatedAt }); }).RequireAuthorization(p => p.RequireRole("Owner"));
        secured.MapPost("/customers", async (CustomerRequest r, AppDbContext db, ClaimsPrincipal principal) => { if (string.IsNullOrWhiteSpace(r.Name)) return Results.BadRequest(new { error = "Customer name is required" }); if (r.Id is Guid id && await db.Customers.FindAsync(id) is Customer existing) return Results.Ok(existing); var c = new Customer { Id = r.Id ?? Guid.NewGuid(), Name = r.Name.Trim(), Phone = r.Phone, CreditLimit = Math.Max(0, r.CreditLimit), Notes = r.Notes }; db.Customers.Add(c); db.AuditEvents.Add(Audit(principal, "Created", "Customer", c.Id.ToString(), c.Name)); await db.SaveChangesAsync(); return Results.Created($"/api/customers/{c.Id}", c); }); secured.MapGet("/customers/summary", async (AppDbContext db) => { var customers = await db.Customers.Where(x => x.Active).ToListAsync(); var sales = await db.Sales.Include(x => x.Payments).Where(x => x.CustomerId != null && (x.Status == "Paid" || x.Status == "Credit" || x.Status == "PartiallyPaid")).ToListAsync(); return customers.Select(c => { var own = sales.Where(x => x.CustomerId == c.Id).ToList(); var spent = own.Sum(x => x.Total); var paid = own.SelectMany(x => x.Payments).Sum(x => x.Amount); return new { c.Id, c.Name, c.Phone, c.CreditLimit, c.Notes, c.Active, totalSpent = spent, debt = Math.Max(0, spent - paid), lastVisit = own.Count == 0 ? (DateTimeOffset?)null : own.Max(x => x.OccurredAt) }; }).OrderByDescending(x => x.totalSpent).ToList(); });
        secured.MapPost("/stock-movements", async (StockRequest r, AppDbContext db, ClaimsPrincipal principal) => { if (await db.StockMovements.FindAsync(r.MovementId) is StockMovement prior) return Results.Ok(new { movement = prior, duplicate = true }); var p = await db.Products.FindAsync(r.ProductId); if (p is null) return Results.NotFound(); p.Stock = Math.Max(0, p.Stock + r.QuantityChange); var m = new StockMovement { Id = r.MovementId, ProductId = p.Id, StaffId = r.StaffId, Type = r.Type, QuantityChange = r.QuantityChange, Notes = r.Notes, OccurredAt = DateTimeOffset.UtcNow }; db.StockMovements.Add(m); db.AuditEvents.Add(Audit(principal, "Stock movement", "Product", p.Id.ToString(), $"{r.Type} {r.QuantityChange} {p.Name}", r.DeviceId)); await db.SaveChangesAsync(); return Results.Ok(new { movement = m, stock = p.Stock, duplicate = false }); }).RequireAuthorization(p => p.RequireRole("Owner", "Manager", "Storekeeper"));
        secured.MapPost("/sales/sync", async (SaleRequest r, AppDbContext db, ClaimsPrincipal principal) => { var existing = await db.Sales.Include(x => x.Items).Include(x => x.Payments).SingleOrDefaultAsync(x => x.DeviceTransactionId == r.DeviceTransactionId); if (existing is not null) return Results.Ok(new { duplicate = true, sale = existing }); await using var tx = await db.Database.BeginTransactionAsync(); var ids = r.Items.Select(x => x.ProductId).ToList(); var products = await db.Products.Where(x => ids.Contains(x.Id)).ToDictionaryAsync(x => x.Id); if (r.Items.Any(x => !products.ContainsKey(x.ProductId))) return Results.BadRequest(new { error = "Unknown product" });var date=DateOnly.FromDateTime(r.OccurredAt.LocalDateTime);var sameDay=(await db.Sales.AsNoTracking().Select(x=>new{x.OccurredAt,x.DailyOrderNumber,x.WalkInNumber}).ToListAsync()).Where(x=>DateOnly.FromDateTime(x.OccurredAt.LocalDateTime)==date).ToList(); var sale = new Sale { DeviceTransactionId = r.DeviceTransactionId, ReceiptNumber = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),DailyOrderNumber=sameDay.Select(x=>x.DailyOrderNumber).DefaultIfEmpty(0).Max()+1,WalkInNumber=r.CustomerId is null?sameDay.Where(x=>x.WalkInNumber!=null).Select(x=>x.WalkInNumber!.Value).DefaultIfEmpty(0).Max()+1:null, CustomerId = r.CustomerId, StaffId = r.StaffId, Status = r.Status, Discount = r.Discount, OccurredAt = r.OccurredAt }; foreach (var line in r.Items) { var p = products[line.ProductId]; sale.Items.Add(new SaleItem { ProductId = p.Id, ProductName = p.Name, Quantity = line.Quantity, UnitPrice = line.UnitPrice, UnitCost = p.CostPrice, Discount = line.Discount }); p.Stock -= line.Quantity; db.StockMovements.Add(new StockMovement { ProductId = p.Id, StaffId = r.StaffId, Type = "Sale", QuantityChange = -line.Quantity, Notes = r.DeviceTransactionId, OccurredAt = r.OccurredAt }); } sale.Total = sale.Items.Sum(x => x.Quantity * x.UnitPrice - x.Discount) - sale.Discount; foreach (var pay in r.Payments) sale.Payments.Add(new Payment { Method = pay.Method, Amount = pay.Amount, PaidAt = r.OccurredAt }); db.Sales.Add(sale); db.AuditEvents.Add(Audit(principal, "Recorded", "Sale", sale.Id.ToString(), $"{r.DeviceTransactionId} total {sale.Total}", r.DeviceId)); await db.SaveChangesAsync(); await tx.CommitAsync(); return Results.Created($"/api/sales/{sale.Id}", new { duplicate = false, sale }); });
        secured.MapPost("/expenses", async (ExpenseRequest r, AppDbContext db, ClaimsPrincipal principal) => { var e = new Expense { Date = r.Date, Category = r.Category, Description = r.Description, Amount = r.Amount, PaidAmount = r.PaidAmount, Method = r.Method }; db.Expenses.Add(e); db.AuditEvents.Add(Audit(principal, "Created", "Expense", e.Id.ToString(), $"{e.Category} {e.Amount}", r.DeviceId)); await db.SaveChangesAsync(); return Results.Created($"/api/expenses/{e.Id}", e); }).RequireAuthorization(p => p.RequireRole("Owner", "Manager")); secured.MapGet("/reports/summary", async (DateOnly from, DateOnly to, AppDbContext db) => { var start = from.ToDateTime(TimeOnly.MinValue, DateTimeKind.Utc); var end = to.AddDays(1).ToDateTime(TimeOnly.MinValue, DateTimeKind.Utc); var sales = (await db.Sales.Where(x => x.Status == "Paid" || x.Status == "Credit" || x.Status == "PartiallyPaid").Include(x => x.Items).Include(x => x.Payments).ToListAsync()).Where(x => x.OccurredAt >= start && x.OccurredAt < end).ToList(); var expenses = await db.Expenses.Where(x => x.Date >= from && x.Date <= to).ToListAsync(); return Results.Ok(new { from, to, revenue = sales.Sum(x => x.Total), cost = sales.SelectMany(x => x.Items).Sum(x => x.UnitCost * x.Quantity), expenses = expenses.Sum(x => x.Amount), salesCount = sales.Count, paymentMix = sales.SelectMany(x => x.Payments).GroupBy(x => x.Method).Select(g => new { method = g.Key, amount = g.Sum(x => x.Amount) }) }); }).RequireAuthorization(p => p.RequireRole("Owner", "Manager")); secured.MapGet("/reports/daily", async (DateOnly from, DateOnly to, AppDbContext db) => { var start = from.ToDateTime(TimeOnly.MinValue, DateTimeKind.Utc); var end = to.AddDays(1).ToDateTime(TimeOnly.MinValue, DateTimeKind.Utc); var sales = (await db.Sales.Where(x => x.Status == "Paid" || x.Status == "Credit" || x.Status == "PartiallyPaid").Include(x => x.Items).ToListAsync()).Where(x => x.OccurredAt >= start && x.OccurredAt < end).ToList(); return sales.GroupBy(x => DateOnly.FromDateTime(x.OccurredAt.UtcDateTime)).Select(g => new { date = g.Key, revenue = g.Sum(x => x.Total), profit = g.Sum(x => x.Total - x.Items.Sum(i => i.UnitCost * i.Quantity)) }).OrderBy(x => x.date).ToList(); }).RequireAuthorization(p => p.RequireRole("Owner", "Manager")); secured.MapGet("/audit", async (int? take, AppDbContext db) => await db.AuditEvents.OrderByDescending(x => x.OccurredAt).Take(Math.Clamp(take ?? 100, 1, 500)).ToListAsync()).RequireAuthorization(p => p.RequireRole("Owner", "Manager"));
        secured.MapPost("/demo/reset", async (AppDbContext db, ClaimsPrincipal principal) => { await DemoData.Ensure(db); db.AuditEvents.Add(Audit(principal, "Reset", "DemoData", null, "Restored marked demo records")); await db.SaveChangesAsync(); return Results.Ok(new { message = "Demo data restored", user = DemoData.UserName, pin = DemoData.Pin }); }).RequireAuthorization(p => p.RequireRole("Owner")); secured.MapDelete("/demo", async (AppDbContext db, ClaimsPrincipal principal) => { await DemoData.Remove(db); db.AuditEvents.Add(Audit(principal, "Deleted", "DemoData", null, "Removed marked demo records")); await db.SaveChangesAsync(); return Results.Ok(new { message = "Demo data removed" }); }).RequireAuthorization(p => p.RequireRole("Owner"));
    }
    static AuditEvent Audit(ClaimsPrincipal p, string action, string type, string? id, string details, string? device = null) => new() { StaffId = Guid.TryParse(p.FindFirst(ClaimTypes.NameIdentifier)?.Value, out var sid) ? sid : null, Actor = p.Identity?.Name ?? "System", Action = action, EntityType = type, EntityId = id, Details = details, DeviceId = device };
}
